package com.example.deepfakedetector.data.local

import android.content.Context
import android.content.SharedPreferences

class PreferenceManager(context: Context) {
    companion object {
        private const val PREF_NAME = "deepfake_detector_prefs"
        private const val KEY_FIRST_LAUNCH = "first_launch"
        private const val KEY_MODEL_VERSION = "model_version"
        private const val KEY_LAST_DETECTION_TIME = "last_detection_time"
        private const val KEY_TOTAL_DETECTIONS = "total_detections"
    }

    private val sharedPreferences: SharedPreferences =
        context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)

    fun isFirstLaunch(): Boolean {
        return sharedPreferences.getBoolean(KEY_FIRST_LAUNCH, true)
    }

    fun setFirstLaunchFalse() {
        sharedPreferences.edit().putBoolean(KEY_FIRST_LAUNCH, false).apply()
    }

    fun getModelVersion(): String {
        return sharedPreferences.getString(KEY_MODEL_VERSION, "1.0.0") ?: "1.0.0"
    }

    fun setModelVersion(version: String) {
        sharedPreferences.edit().putString(KEY_MODEL_VERSION, version).apply()
    }

    fun getLastDetectionTime(): Long {
        return sharedPreferences.getLong(KEY_LAST_DETECTION_TIME, 0)
    }

    fun setLastDetectionTime(timestamp: Long) {
        sharedPreferences.edit().putLong(KEY_LAST_DETECTION_TIME, timestamp).apply()
    }

    fun getTotalDetections(): Int {
        return sharedPreferences.getInt(KEY_TOTAL_DETECTIONS, 0)
    }

    fun incrementTotalDetections() {
        val current = getTotalDetections()
        sharedPreferences.edit().putInt(KEY_TOTAL_DETECTIONS, current + 1).apply()
    }

    fun clearPreferences() {
        sharedPreferences.edit().clear().apply()
    }
}

package com.example.deepfakedetector.data.local

import android.content.Context
import android.content.SharedPreferences
import android.util.Log

class PreferenceManager(context: Context) {
    companion object {
        private const val PREF_NAME = "deepfake_detector_prefs"
        private const val KEY_FIRST_LAUNCH = "first_launch"
        private const val KEY_MODEL_VERSION = "model_version"
        private const val KEY_LAST_DETECTION_TIME = "last_detection_time"
        private const val KEY_TOTAL_DETECTIONS = "total_detections"
    }

    private val sharedPreferences: SharedPreferences = try {
        context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE).also {
            Log.d("PreferenceManager", "SharedPreferences initialized")
        }
    } catch (e: Exception) {
        Log.e("PreferenceManager", "Error initializing SharedPreferences: ${e.message}", e)
        throw e
    }

    fun isFirstLaunch(): Boolean {
        return try {
            sharedPreferences.getBoolean(KEY_FIRST_LAUNCH, true)
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in isFirstLaunch: ${e.message}", e)
            true
        }
    }

    fun setFirstLaunchFalse() {
        try {
            sharedPreferences.edit().putBoolean(KEY_FIRST_LAUNCH, false).apply()
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in setFirstLaunchFalse: ${e.message}", e)
        }
    }

    fun getModelVersion(): String {
        return try {
            sharedPreferences.getString(KEY_MODEL_VERSION, "1.0.0") ?: "1.0.0"
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in getModelVersion: ${e.message}", e)
            "1.0.0"
        }
    }

    fun setModelVersion(version: String) {
        try {
            sharedPreferences.edit().putString(KEY_MODEL_VERSION, version).apply()
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in setModelVersion: ${e.message}", e)
        }
    }

    fun getLastDetectionTime(): Long {
        return try {
            sharedPreferences.getLong(KEY_LAST_DETECTION_TIME, 0)
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in getLastDetectionTime: ${e.message}", e)
            0
        }
    }

    fun setLastDetectionTime(timestamp: Long) {
        try {
            sharedPreferences.edit().putLong(KEY_LAST_DETECTION_TIME, timestamp).apply()
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in setLastDetectionTime: ${e.message}", e)
        }
    }

    fun getTotalDetections(): Int {
        return try {
            sharedPreferences.getInt(KEY_TOTAL_DETECTIONS, 0)
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in getTotalDetections: ${e.message}", e)
            0
        }
    }

    fun incrementTotalDetections() {
        try {
            val current = getTotalDetections()
            sharedPreferences.edit().putInt(KEY_TOTAL_DETECTIONS, current + 1).apply()
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in incrementTotalDetections: ${e.message}", e)
        }
    }

    fun clearPreferences() {
        try {
            sharedPreferences.edit().clear().apply()
        } catch (e: Exception) {
            Log.e("PreferenceManager", "Error in clearPreferences: ${e.message}", e)
        }
    }
}

package com.example.deepfakedetector.ui.main

import android.content.Intent
import android.graphics.Bitmap
import android.net.Uri
import android.os.Bundle
import android.view.View
import android.widget.ImageView
import android.widget.ProgressBar
import android.widget.TextView
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.google.android.material.button.MaterialButton
import com.example.deepfakedetector.R
import com.example.deepfakedetector.data.model.DetectionResult
import com.example.deepfakedetector.repository.DetectionRepository
import com.example.deepfakedetector.ui.history.HistoryActivity
import com.example.deepfakedetector.ui.result.ResultActivity
import com.example.deepfakedetector.utils.ImageUtils
import kotlinx.coroutines.launch

class MainActivity : AppCompatActivity() {

    private lateinit var repository: DetectionRepository

    private lateinit var imageViewPreview: ImageView
    private lateinit var imageViewLogo: ImageView
    private lateinit var buttonCamera: MaterialButton
    private lateinit var buttonGallery: MaterialButton
    private lateinit var buttonDetect: MaterialButton
    private lateinit var buttonHistory: MaterialButton
    private lateinit var progressBar: ProgressBar
    private lateinit var textViewStatus: TextView
    private lateinit var textViewPlaceholder: TextView

    private var selectedImageUri: Uri? = null
    private var capturedBitmap: Bitmap? = null

    private val galleryLauncher =
        registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
            uri?.let {
                selectedImageUri = it
                capturedBitmap = null
                imageViewPreview.setImageURI(it)
                imageViewPreview.visibility = View.VISIBLE
                textViewPlaceholder.visibility = View.GONE
                textViewStatus.text = getString(R.string.image_selected)
            }
        }

    private val cameraLauncher =
        registerForActivityResult(ActivityResultContracts.TakePicturePreview()) { bitmap: Bitmap? ->
            bitmap?.let {
                capturedBitmap = it
                selectedImageUri = null
                imageViewPreview.setImageBitmap(it)
                imageViewPreview.visibility = View.VISIBLE
                textViewPlaceholder.visibility = View.GONE
                textViewStatus.text = getString(R.string.image_captured)
            }
        }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        repository = DetectionRepository(this)

        initViews()
        setupListeners()
        setupInitialUI()
    }

    private fun initViews() {
        imageViewLogo = findViewById(R.id.imageViewLogo)
        imageViewPreview = findViewById(R.id.imageViewPreview)
        buttonCamera = findViewById(R.id.buttonCamera)
        buttonGallery = findViewById(R.id.buttonGallery)
        buttonDetect = findViewById(R.id.buttonDetect)
        buttonHistory = findViewById(R.id.buttonHistory)
        progressBar = findViewById(R.id.progressBar)
        textViewStatus = findViewById(R.id.textViewStatus)
        textViewPlaceholder = findViewById(R.id.textViewPlaceholder)
    }

    private fun setupInitialUI() {
        progressBar.visibility = View.GONE
        imageViewPreview.visibility = View.VISIBLE
        textViewPlaceholder.visibility = View.VISIBLE
        textViewStatus.text = getString(R.string.status_ready)
    }

    private fun setupListeners() {
        buttonCamera.setOnClickListener {
            launchCamera()
        }

        buttonGallery.setOnClickListener {
            launchGallery()
        }

        buttonDetect.setOnClickListener {
            detectDeepfake()
        }

        buttonHistory.setOnClickListener {
            openHistory()
        }
    }

    private fun launchCamera() {
        cameraLauncher.launch(null)
    }

    private fun launchGallery() {
        galleryLauncher.launch("image/*")
    }

    private fun openHistory() {
        startActivity(Intent(this, HistoryActivity::class.java))
    }

    private fun detectDeepfake() {
        val uri = selectedImageUri
        val bmp = capturedBitmap

        if (uri == null && bmp == null) {
            textViewStatus.text = getString(R.string.status_select_or_capture)
            return
        }

        lifecycleScope.launch {
            try {
                showLoading(true)
                textViewStatus.text = getString(R.string.status_detecting)

                val bitmapToAnalyze = uri?.let {
                    ImageUtils.loadBitmapFromUri(this@MainActivity, it)
                } ?: bmp

                if (bitmapToAnalyze == null) {
                    showLoading(false)
                    textViewStatus.text = getString(R.string.status_failed_to_load)
                    return@launch
                }

                val result = repository.detectDeepfake(bitmapToAnalyze)
                showLoading(false)
                navigateToResult(result)

            } catch (e: Exception) {
                showLoading(false)
                textViewStatus.text = getString(R.string.status_error, e.message ?: "Unknown error")
            }
        }
    }

    private fun showLoading(isLoading: Boolean) {
        progressBar.visibility = if (isLoading) View.VISIBLE else View.GONE
        buttonDetect.isEnabled = !isLoading
        buttonCamera.isEnabled = !isLoading
        buttonGallery.isEnabled = !isLoading
        buttonHistory.isEnabled = !isLoading
    }

    private fun navigateToResult(result: DetectionResult) {
        val intent = Intent(this, ResultActivity::class.java).apply {
            putExtra("confidence_score", result.confidenceScore)
            putExtra("result_label", if (result.isFakeface) "Deepfake" else "Real")
        }
        startActivity(intent)
    }

    override fun onDestroy() {
        super.onDestroy()
        repository.close()
    }
}

package com.example.deepfakedetector.ui.main

import android.content.Intent
import android.graphics.Bitmap
import android.net.Uri
import android.os.Bundle
import android.view.View
import android.widget.ImageView
import android.widget.ProgressBar
import android.widget.TextView
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.google.android.material.button.MaterialButton
import com.example.deepfakedetector.R
import com.example.deepfakedetector.data.model.DetectionResult
import com.example.deepfakedetector.repository.DetectionRepository
import com.example.deepfakedetector.ui.history.HistoryActivity
import com.example.deepfakedetector.ui.result.ResultActivity
import com.example.deepfakedetector.utils.ImageUtils
import com.example.deepfakedetector.utils.PermissionUtils
import kotlinx.coroutines.launch

class MainActivity : AppCompatActivity() {

    private lateinit var repository: DetectionRepository

    private lateinit var imageViewPreview: ImageView
    private lateinit var imageViewLogo: ImageView
    private lateinit var buttonCamera: MaterialButton
    private lateinit var buttonGallery: MaterialButton
    private lateinit var buttonDetect: MaterialButton
    private lateinit var buttonHistory: MaterialButton
    private lateinit var progressBar: ProgressBar
    private lateinit var textViewStatus: TextView
    private lateinit var textViewPlaceholder: TextView

    private var selectedImageUri: Uri? = null
    private var capturedBitmap: Bitmap? = null

    private val galleryLauncher =
        registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
            uri?.let {
                selectedImageUri = it
                capturedBitmap = null
                imageViewPreview.setImageURI(it)
                imageViewPreview.visibility = View.VISIBLE
                textViewPlaceholder.visibility = View.GONE
                textViewStatus.text = getString(R.string.image_selected)
            }
        }

    private val cameraLauncher =
        registerForActivityResult(ActivityResultContracts.TakePicturePreview()) { bitmap: Bitmap? ->
            bitmap?.let {
                capturedBitmap = it
                selectedImageUri = null
                imageViewPreview.setImageBitmap(it)
                imageViewPreview.visibility = View.VISIBLE
                textViewPlaceholder.visibility = View.GONE
                textViewStatus.text = getString(R.string.image_captured)
            }
        }

    private val requestPermissionLauncher =
        registerForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { permissions ->
            val allGranted = permissions.all { it.value }
            if (allGranted) {
                // All permissions granted, proceed with the operation
            }
        }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        try {
            setContentView(R.layout.activity_main)

            repository = DetectionRepository(this)

            initViews()
            setupListeners()
            setupInitialUI()

            // Request permissions on app start
            checkAndRequestPermissions()
        } catch (e: Exception) {
            e.printStackTrace()
            android.util.Log.e("MainActivity", "Error in onCreate: ${e.message}", e)
            finish()
        }
    }

    private fun initViews() {
        try {
            imageViewLogo = findViewById(R.id.imageViewLogo)
            imageViewPreview = findViewById(R.id.imageViewPreview)
            buttonCamera = findViewById(R.id.buttonCamera)
            buttonGallery = findViewById(R.id.buttonGallery)
            buttonDetect = findViewById(R.id.buttonDetect)
            buttonHistory = findViewById(R.id.buttonHistory)
            progressBar = findViewById(R.id.progressBar)
            textViewStatus = findViewById(R.id.textViewStatus)
            textViewPlaceholder = findViewById(R.id.textViewPlaceholder)

            android.util.Log.d("MainActivity", "All views initialized successfully")
        } catch (e: Exception) {
            e.printStackTrace()
            android.util.Log.e("MainActivity", "Error initializing views: ${e.message}", e)
            throw e
        }
    }

    private fun setupInitialUI() {
        try {
            progressBar.visibility = View.GONE
            imageViewPreview.visibility = View.VISIBLE
            textViewPlaceholder.visibility = View.VISIBLE
            textViewStatus.text = getString(R.string.status_ready)
            android.util.Log.d("MainActivity", "Initial UI setup completed")
        } catch (e: Exception) {
            android.util.Log.e("MainActivity", "Error in setupInitialUI: ${e.message}", e)
        }
    }

    private fun setupListeners() {
        buttonCamera.setOnClickListener {
            launchCamera()
        }

        buttonGallery.setOnClickListener {
            launchGallery()
        }

        buttonDetect.setOnClickListener {
            detectDeepfake()
        }

        buttonHistory.setOnClickListener {
            openHistory()
        }
    }

    private fun checkAndRequestPermissions() {
        val missingPermissions = PermissionUtils.getMissingPermissions(this)
        if (missingPermissions.isNotEmpty()) {
            requestPermissionLauncher.launch(missingPermissions)
        }
    }

    private fun launchCamera() {
        cameraLauncher.launch(null)
    }

    private fun launchGallery() {
        galleryLauncher.launch("image/*")
    }

    private fun openHistory() {
        startActivity(Intent(this, HistoryActivity::class.java))
    }

    private fun detectDeepfake() {
        val uri = selectedImageUri
        val bmp = capturedBitmap

        if (uri == null && bmp == null) {
            textViewStatus.text = getString(R.string.status_select_or_capture)
            return
        }

        lifecycleScope.launch {
            try {
                showLoading(true)
                textViewStatus.text = getString(R.string.status_detecting)

                val bitmapToAnalyze = uri?.let {
                    ImageUtils.loadBitmapFromUri(this@MainActivity, it)
                } ?: bmp

                if (bitmapToAnalyze == null) {
                    showLoading(false)
                    textViewStatus.text = getString(R.string.status_failed_to_load)
                    return@launch
                }

                val result = repository.detectDeepfake(bitmapToAnalyze)
                showLoading(false)
                navigateToResult(result)

            } catch (e: Exception) {
                showLoading(false)
                android.util.Log.e("MainActivity", "Error detecting deepfake: ${e.message}", e)
                textViewStatus.text = getString(R.string.status_error, e.message ?: "Unknown error")
            }
        }
    }

    private fun showLoading(isLoading: Boolean) {
        progressBar.visibility = if (isLoading) View.VISIBLE else View.GONE
        buttonDetect.isEnabled = !isLoading
        buttonCamera.isEnabled = !isLoading
        buttonGallery.isEnabled = !isLoading
        buttonHistory.isEnabled = !isLoading
    }

    private fun navigateToResult(result: DetectionResult) {
        val intent = Intent(this, ResultActivity::class.java).apply {
            putExtra("confidence_score", result.confidenceScore)
            putExtra("result_label", if (result.isFakeface) "Deepfake" else "Real")
        }
        startActivity(intent)
    }

    override fun onDestroy() {
        super.onDestroy()
        repository.close()
    }
}

package com.example.deepfakedetector.ml

import android.graphics.Bitmap
import android.graphics.Matrix

class ImagePreprocessor {
    companion object {
        private const val INPUT_WIDTH = 224
        private const val INPUT_HEIGHT = 224
    }

    fun preprocessImage(bitmap: Bitmap): Bitmap {
        // Resize image to model input size
        val resized = Bitmap.createScaledBitmap(bitmap, INPUT_WIDTH, INPUT_HEIGHT, true)

        // Normalize pixel values if needed
        return resized
    }

    fun cropToSquare(bitmap: Bitmap): Bitmap {
        val size = if (bitmap.width < bitmap.height) bitmap.width else bitmap.height
        val x = (bitmap.width - size) / 2
        val y = (bitmap.height - size) / 2
        return Bitmap.createBitmap(bitmap, x, y, size, size)
    }

    fun rotateBitmap(bitmap: Bitmap, degrees: Float): Bitmap {
        val matrix = Matrix()
        matrix.postRotate(degrees)
        return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
    }
}

package com.example.deepfakedetector.ml

import android.graphics.Bitmap
import android.graphics.Matrix
import android.util.Log

class ImagePreprocessor {
    companion object {
        private const val INPUT_WIDTH = 224
        private const val INPUT_HEIGHT = 224
    }

    fun preprocessImage(bitmap: Bitmap): Bitmap {
        return try {
            // Resize image to model input size
            val resized = Bitmap.createScaledBitmap(bitmap, INPUT_WIDTH, INPUT_HEIGHT, true)
            Log.d("ImagePreprocessor", "Image preprocessing completed: ${INPUT_WIDTH}x${INPUT_HEIGHT}")
            resized
        } catch (e: Exception) {
            Log.e("ImagePreprocessor", "Error preprocessing image: ${e.message}", e)
            // Return original bitmap if preprocessing fails
            bitmap
        }
    }

    fun cropToSquare(bitmap: Bitmap): Bitmap {
        return try {
            val size = if (bitmap.width < bitmap.height) bitmap.width else bitmap.height
            val x = (bitmap.width - size) / 2
            val y = (bitmap.height - size) / 2
            Bitmap.createBitmap(bitmap, x, y, size, size)
        } catch (e: Exception) {
            Log.e("ImagePreprocessor", "Error cropping image: ${e.message}", e)
            bitmap
        }
    }

    fun rotateBitmap(bitmap: Bitmap, degrees: Float): Bitmap {
        return try {
            val matrix = Matrix()
            matrix.postRotate(degrees)
            Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
        } catch (e: Exception) {
            Log.e("ImagePreprocessor", "Error rotating image: ${e.message}", e)
            bitmap
        }
    }
}

