package com.example.deepfakedetector.utils

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.net.Uri
import android.content.Context
import java.io.InputStream

object ImageUtils {
    const val MAX_WIDTH = 1024
    const val MAX_HEIGHT = 1024

    fun loadBitmapFromUri(context: Context, uri: Uri): Bitmap? {
        return try {
            val inputStream = context.contentResolver.openInputStream(uri)
            inputStream?.use { BitmapFactory.decodeStream(it) }
        } catch (e: Exception) {
            e.printStackTrace()
            null
        }
    }

    fun scaleBitmap(bitmap: Bitmap, maxWidth: Int = MAX_WIDTH, maxHeight: Int = MAX_HEIGHT): Bitmap {
        val width = bitmap.width
        val height = bitmap.height

        if (width <= maxWidth && height <= maxHeight) {
            return bitmap
        }

        val aspectRatio = width.toFloat() / height.toFloat()
        val newWidth: Int
        val newHeight: Int

        if (width > height) {
            newWidth = maxWidth
            newHeight = (maxWidth / aspectRatio).toInt()
        } else {
            newHeight = maxHeight
            newWidth = (maxHeight * aspectRatio).toInt()
        }

        return Bitmap.createScaledBitmap(bitmap, newWidth, newHeight, true)
    }

    fun compressBitmap(bitmap: Bitmap, quality: Int = 80): Bitmap {
        val stream = java.io.ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.JPEG, quality, stream)
        val bytes = stream.toByteArray()
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }
}

package com.example.deepfakedetector.utils

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.net.Uri
import android.content.Context
import android.util.Log
import java.io.InputStream

object ImageUtils {
    const val MAX_WIDTH = 1024
    const val MAX_HEIGHT = 1024

    fun loadBitmapFromUri(context: Context, uri: Uri): Bitmap? {
        return try {
            val inputStream = context.contentResolver.openInputStream(uri)
            inputStream?.use { BitmapFactory.decodeStream(it) }.also {
                Log.d("ImageUtils", "Successfully loaded bitmap from URI")
            }
        } catch (e: Exception) {
            Log.e("ImageUtils", "Error loading bitmap from URI: ${e.message}", e)
            e.printStackTrace()
            null
        }
    }

    fun scaleBitmap(bitmap: Bitmap, maxWidth: Int = MAX_WIDTH, maxHeight: Int = MAX_HEIGHT): Bitmap {
        return try {
            val width = bitmap.width
            val height = bitmap.height

            if (width <= maxWidth && height <= maxHeight) {
                return bitmap
            }

            val aspectRatio = width.toFloat() / height.toFloat()
            val newWidth: Int
            val newHeight: Int

            if (width > height) {
                newWidth = maxWidth
                newHeight = (maxWidth / aspectRatio).toInt()
            } else {
                newHeight = maxHeight
                newWidth = (maxHeight * aspectRatio).toInt()
            }

            Bitmap.createScaledBitmap(bitmap, newWidth, newHeight, true).also {
                Log.d("ImageUtils", "Bitmap scaled to ${newWidth}x${newHeight}")
            }
        } catch (e: Exception) {
            Log.e("ImageUtils", "Error scaling bitmap: ${e.message}", e)
            bitmap
        }
    }

    fun compressBitmap(bitmap: Bitmap, quality: Int = 80): Bitmap {
        return try {
            val stream = java.io.ByteArrayOutputStream()
            bitmap.compress(Bitmap.CompressFormat.JPEG, quality, stream)
            val bytes = stream.toByteArray()
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size).also {
                Log.d("ImageUtils", "Bitmap compressed successfully")
            }
        } catch (e: Exception) {
            Log.e("ImageUtils", "Error compressing bitmap: ${e.message}", e)
            bitmap
        }
    }
}

package com.example.deepfakedetector.utils

import android.Manifest
import android.content.Context
import android.content.pm.PackageManager
import androidx.core.content.ContextCompat

object PermissionUtils {
    val REQUIRED_PERMISSIONS = arrayOf(
        Manifest.permission.CAMERA,
        Manifest.permission.READ_EXTERNAL_STORAGE,
        Manifest.permission.WRITE_EXTERNAL_STORAGE
    )

    const val PERMISSION_REQUEST_CODE = 100

    fun hasPermission(context: Context, permission: String): Boolean {
        return ContextCompat.checkSelfPermission(context, permission) == PackageManager.PERMISSION_GRANTED
    }

    fun hasAllPermissions(context: Context): Boolean {
        return REQUIRED_PERMISSIONS.all { hasPermission(context, it) }
    }

    fun getMissingPermissions(context: Context): Array<String> {
        return REQUIRED_PERMISSIONS.filter { !hasPermission(context, it) }.toTypedArray()
    }
}

package com.example.deepfakedetector.utils

import android.Manifest
import android.content.Context
import android.content.pm.PackageManager
import android.os.Build
import androidx.core.content.ContextCompat

object PermissionUtils {
    val REQUIRED_PERMISSIONS = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        // Android 13+ uses new photo/video picker permissions
        arrayOf(
            Manifest.permission.CAMERA,
            Manifest.permission.READ_MEDIA_IMAGES,
            Manifest.permission.READ_MEDIA_VIDEO
        )
    } else {
        // Android 12 and below
        arrayOf(
            Manifest.permission.CAMERA,
            Manifest.permission.READ_EXTERNAL_STORAGE
        )
    }

    const val PERMISSION_REQUEST_CODE = 100

    fun hasPermission(context: Context, permission: String): Boolean {
        return ContextCompat.checkSelfPermission(context, permission) == PackageManager.PERMISSION_GRANTED
    }

    fun hasAllPermissions(context: Context): Boolean {
        return REQUIRED_PERMISSIONS.all { hasPermission(context, it) }
    }

    fun getMissingPermissions(context: Context): Array<String> {
        return REQUIRED_PERMISSIONS.filter { !hasPermission(context, it) }.toTypedArray()
    }
}

